/// <summary>
/// desiged from AVA
/// </summary>
public void init()
{
    next init();

    SalesTable_ProjId.visible(false);
    SalesTable_DeliveryDateControl.visible(false);
    ConfirmDates.visible(false);
    this.design().controlName(formControlStr(SalesCreateOrder, groupAdministration_SalesUnitId)).visible(false);
    this.design().controlName(formControlStr(SalesCreateOrder, groupAdministration_PersonSalesResponsible)).visible(false);
    this.design().controlName(formControlStr(SalesCreateOrder, SalesTable_MCRExpedite)).visible(false);
    this.design().controlName(formControlStr(SalesCreateOrder, editSalesAgreementId)).visible(false);       

    //this.avaInitFromAVASalesParameters();
}

 /// <summary>
 ///     AVA <c>avaCustAccountChanged</c> method.
 ///     AVA - Schneider 12.03.2024
 /// </summary>
public void avaCustAccountChanged()
 {
     FormDataSource  locFormDataSource;
     SalesTable      locSalesTable;
     CustTable       locCustTable;

     locFormDataSource   = SalesTable_DS;
     locSalesTable       = locFormDataSource.cursor();

     if (salesTableForm.parmReturnStatus() == ReturnStatusHeader::Created)
     {
         if(locSalesTable.CustAccount)
         {
             locSalesTable.avaInitCustAccountChanged_ReturnItem();
         }
     }

 }

/// <summary>
///     AVA <c>avaInitFromAVASalesParameters</c> method.
///     AVA - Schneider 12.03.2024
/// </summary>
public void avaInitFromAVASalesParameters()
{
    FormDataSource      locFormDataSource;
    SalesTable          locSalesTable;

    AVASalesParameters  locAVASalesParameters;

    locFormDataSource       = SalesTable_DS;
    locSalesTable           = locFormDataSource.cursor();

    if (this.salesTableForm.parmReturnStatus() == ReturnStatusHeader::Created)
    {
        locAVASalesParameters   = AVASalesParameters::find();

        if(     locAVASalesParameters.AutomaticICOrders
            &&  locAVASalesParameters.KCS_IC_Reduction  )
        {
            locSalesTable.avaInitFromAVASalesParameters_ReturnItem();
        }
    }
}

/// <summary>
///     AVA <c>avaInitFreightSettings_ReturnItem</c> method.
///     AVA - Schneider 13.03.2024
/// </summary>
public void avaInitFreightSettings_ReturnItem()
{
    FormDataSource  locFormDataSource;
    SalesTable      locSalesTable;

    locFormDataSource   = SalesTable_DS;
    locSalesTable       = locFormDataSource.cursor();

    if (salesTableForm.parmReturnStatus() == ReturnStatusHeader::Created)
    {
        locSalesTable.avaInitFreightSettings_ReturnItem();
    }
}
